using System;using System.IO;using System.Text.RegularExpressions;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;
// 洞窟床の共有計算・書出し材質を隔離Unityで検査する。ゲーム本体は変更しない。
public static class CaveFloorChecks {
 [Serializable]class Reference {public int width,height;public float[] color,relief;}
 [Serializable]class Report {public string status,error;public int checks;public float maxColorError,maxReliefError;}
 static int checks;static void Check(bool b,string s){checks++;if(!b)throw new Exception(s);}static string Arg(string s){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,s)+1];}
 public static void Run(){string output=Arg("-cave-floor-output");var report=new Report();int exit=0;try {
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);string export=Path.Combine(output,"export"),file=Path.Combine(export,"shared_ground.json");
  var result=MapSharedGroundBuilder.Build(file,Vector2.zero);Check(result.material.IsKeywordEnabled("CAVE_FLOOR"),"Cave material enabled");
  var mask=(Texture2D)result.material.GetTexture("_CaveSurfaceMask");var importer=(TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(mask));Check(mask.width==49&&mask.height==49&&!importer.sRGBTexture&&!importer.mipmapEnabled&&importer.filterMode==FilterMode.Bilinear,"Raw mask import");
  Check(result.material.GetVector("_CaveMaskParams")==new Vector4(12,49,1,0),"World metres and pixel centres");
  string legacy=Path.Combine(output,"legacy-ground.json");File.WriteAllText(legacy,Regex.Replace(File.ReadAllText(file),",\\s*\"caveFloor\"\\s*:\\s*\\{[^{}]*\\}",""));var old=MapSharedGroundBuilder.Build(legacy,Vector2.zero);Check(!old.material.IsKeywordEnabled("CAVE_FLOOR"),"Legacy ground contract remains valid");
  string invalid=Path.Combine(output,"invalid-ground.json");File.WriteAllText(invalid,File.ReadAllText(file).Replace(MapSharedProps.SharedCaveFloorContract.Hash,new string('0',64)));bool rejected=false;try{MapSharedGroundBuilder.Build(invalid,Vector2.zero);}catch(InvalidDataException){rejected=true;}Check(rejected,"Reject mismatched floor source");
  var reference=JsonUtility.FromJson<Reference>(File.ReadAllText(Path.Combine(output,"floor-gpu-reference.json")));var probe=new Material(Shader.Find("Hidden/MapSharedProps/CaveFloorProbe"));Check(probe.shader.isSupported,"GPU probe available");
  for(int mode=0;mode<2;mode++){probe.SetFloat("_Mode",mode);var rt=new RenderTexture(reference.width,reference.height,0,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear);rt.Create();Graphics.Blit(Texture2D.blackTexture,rt,probe);foreach(var message in ShaderUtil.GetShaderMessages(probe.shader))Check(message.severity.ToString()!="Error",message.message);var previous=RenderTexture.active;RenderTexture.active=rt;var read=new Texture2D(reference.width,reference.height,TextureFormat.RGBAFloat,false,true);read.ReadPixels(new Rect(0,0,reference.width,reference.height),0,0);read.Apply();var pixels=read.GetPixels();var expected=mode==0?reference.color:reference.relief;float maximum=0;for(int i=0;i<pixels.Length;i++)for(int c=0;c<4;c++){float delta=Mathf.Abs(pixels[i][c]-expected[i*4+c]);maximum=Mathf.Max(maximum,delta);Check(!float.IsNaN(delta)&&!float.IsInfinity(delta),"Finite sample");}if(mode==0)report.maxColorError=maximum;else report.maxReliefError=maximum;RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(read);}
  Check(report.maxColorError<.0002f,"Browser/Unity color and wet difference "+report.maxColorError);Check(report.maxReliefError<.000005f,"Browser/Unity relief difference "+report.maxReliefError);
  var rendererData=ScriptableObject.CreateInstance<UniversalRendererData>();var pipeline=UniversalRenderPipelineAsset.Create(rendererData);pipeline.shadowDistance=40;var serialized=new SerializedObject(pipeline);serialized.FindProperty("m_MainLightShadowsSupported").boolValue=true;serialized.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=pipeline;QualitySettings.renderPipeline=pipeline;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.35f,.37f,.4f);
  var built=MapSharedPropsBuilder.Build(export);Check(built.placed==3&&built.skipped==0,"Cave props retained");var flowMaterial=built.prefabs["flowstone"].GetComponent<Renderer>().sharedMaterial;Check(flowMaterial.IsKeywordEnabled("CAVE_FLOW_SHADOW"),"Flowstone-only shadow correction");foreach(var entry in built.prefabs)if(entry.Key!="flowstone")Check(!entry.Value.GetComponent<Renderer>().sharedMaterial.IsKeywordEnabled("CAVE_FLOW_SHADOW"),"Other shadows unchanged");
  built.root.transform.position=new Vector3(-12,-1.44f,-12);
  var floor=new GameObject("Cave floor preview");var mesh=new Mesh();mesh.vertices=new[]{new Vector3(-12,-1.44f,-12),new Vector3(12,1.44f,-12),new Vector3(-12,-1.44f,12),new Vector3(12,1.44f,12)};mesh.triangles=new[]{0,2,1,1,2,3};mesh.RecalculateNormals();mesh.RecalculateBounds();floor.AddComponent<MeshFilter>().sharedMesh=mesh;floor.AddComponent<MeshRenderer>().sharedMaterial=result.material;
  var sun=new GameObject("Preview sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.8f;sun.shadows=LightShadows.Hard;sun.transform.rotation=Quaternion.LookRotation(new Vector3(5,-9,4));sun.gameObject.AddComponent<UniversalAdditionalLightData>();
  var person=GameObject.CreatePrimitive(PrimitiveType.Capsule);person.transform.position=new Vector3(-1.8f,.9f-1.8f*.12f,-1.2f);person.transform.localScale=new Vector3(.35f,.9f,.35f);
  var camera=new GameObject("Preview camera").AddComponent<Camera>();camera.gameObject.AddComponent<UniversalAdditionalCameraData>();camera.farClipPlane=100;camera.fieldOfView=45;camera.aspect=1.333333f;camera.backgroundColor=Color.black;camera.clearFlags=CameraClearFlags.SolidColor;
  foreach(bool bias in new[]{false,true}){if(bias)flowMaterial.EnableKeyword("CAVE_FLOW_SHADOW");else flowMaterial.DisableKeyword("CAVE_FLOW_SHADOW");
  foreach(string view in new[]{"top","walk","low"}){camera.transform.position=view=="top"?new Vector3(0,14,0):view=="walk"?new Vector3(8,2.76f,-10):new Vector3(7,1.64f,-9);camera.transform.up=view=="top"?Vector3.back:Vector3.up;camera.transform.LookAt(new Vector3(.2f,.6f,0));var planes=GeometryUtility.CalculateFrustumPlanes(camera);foreach(var r in built.root.GetComponentsInChildren<Renderer>())Check(GeometryUtility.TestPlanesAABB(planes,r.bounds),"Prop visible in "+view);Capture(camera,Path.Combine(output,"unity-floor-"+view+"-"+(bias?"after":"before")+".png"));}}
  foreach(var message in ShaderUtil.GetShaderMessages(flowMaterial.shader))Check(message.severity.ToString()!="Error",message.message);foreach(var message in ShaderUtil.GetShaderMessages(result.material.shader))Check(message.severity.ToString()!="Error",message.message);report.status="Passed";
 }catch(Exception e){exit=1;report.status="Failed";report.error=e.ToString();Debug.LogException(e);}report.checks=checks;File.WriteAllText(Path.Combine(output,"unity-floor.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(exit);}
 static void Capture(Camera camera,string file){var rt=new RenderTexture(1200,900,24);rt.Create();camera.targetTexture=rt;RenderPipeline.SubmitRenderRequest(camera,new RenderPipeline.StandardRequest{destination=rt});var previous=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1200,900,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,1200,900),0,0);image.Apply();File.WriteAllBytes(file,image.EncodeToPNG());RenderTexture.active=previous;camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(image);}
}
